"""Generate the static HCI portfolio pages. Run with python build_portfolio.py."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).parent


def shell(title, current, body, description):
    nav = [('Work', 'index.html#work'), ('About', 'about.html'), ('Lab', 'lab.html'), ('Resume', 'resume.html')]
    links = ''.join(f'<a href="{url}"{(" aria-current=\"page\"" if name == current else "")}>{name}</a>' for name, url in nav)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="{escape(description, quote=True)}"><title>{escape(title)} — Allena Oglivie</title>
<link rel="icon" href="public/logo.png"><link rel="stylesheet" href="css/portfolio.css">
<script>try{{document.documentElement.dataset.theme=localStorage.getItem('portfolio-theme')||'dark'}}catch(e){{}}</script></head>
<body><a class="skip-link" href="#main">Skip to content</a>
<header class="site-header"><nav class="nav-inner container" aria-label="Primary"><a class="brand" href="index.html"><span class="brand-mark" aria-hidden="true">✳</span>Allena Oglivie</a><div class="nav-links">{links}<a href="https://github.com/Cryphixi" aria-label="GitHub profile">GitHub ↗</a><a href="https://www.linkedin.com/in/allena-oglivie/" aria-label="LinkedIn profile">LinkedIn ↗</a><button class="theme-toggle" type="button">Light mode</button></div></nav></header>
<main id="main">{body}</main>
<footer class="site-footer"><div class="container footer-inner"><div><p class="eyebrow">Let's make things easier to use</p><p>Interested in player experience, onboarding, or human-centered tools? <a href="mailto:ogfay05@gmail.com">Email me</a>.</p></div><div class="footer-links"><a href="mailto:ogfay05@gmail.com">Email</a><a href="https://github.com/Cryphixi">GitHub</a><a href="https://www.linkedin.com/in/allena-oglivie/">LinkedIn</a><a href="public/Allena_Oglivie_Resume.pdf">Resume PDF</a></div></div></footer>
<script src="js/portfolio.js" defer></script></body></html>'''


studies = [
    dict(slug='gamesmanuni', title='GamesmanUni Redesign', eyebrow='01 / GamesCrafters · UC Berkeley', outcome='Redesigning a research platform of 107 games and puzzles so new players find what they want without getting lost.', image='public/timeline/gc-frontend-dan.jpg', alt='Allena with GamesCrafters collaborator Dan Garcia', caption='GamesCrafters team photo. Platform screenshots and before/after comparisons still needed.', role='Website Lead', team='GamesCrafters', timeline='2025–present', tools='[ADD TOOLS]', skills='UX observation, information architecture, frontend design', tags=['Website Lead', '2025–present', 'UX research'], problem='GamesmanUni brings together games and puzzles, but people arriving with different levels of familiarity had trouble finding a starting point. Watching both new and veteran members get confused made navigation and discovery the central design problem.', process='The work started with observing where new and veteran members became confused. The team reviews designs every five weeks. The redesign brings games and puzzles into one page, adds a 17-tag filter system across four categories, and updates four pages. A 25th anniversary prototype extends the same exploration.', decisions=[('Unify discovery', 'One games and puzzles page gives visitors a shared starting point instead of making them choose a content type first.'), ('Filter with meaning', 'Seventeen tags across four categories offer multiple ways to narrow the library. [ADD FILTER SYSTEM DIAGRAM]'), ('Review with the team', 'Design reviews every five weeks create a recurring point to examine confusing flows and revise the pages. [ADD BEFORE/AFTER SCREENSHOTS]')], result='Four pages have been redesigned and the games and puzzles browser has a 17-tag filter system. [ADD USER FEEDBACK OR MEASURED OUTCOME] The 25th anniversary prototype is another opportunity to test how people enter the collection.', learned=['Observation can reveal navigation problems before a visual redesign begins.', 'A shared taxonomy has to make sense to newcomers and experienced players alike.', '[ADD PERSONAL REFLECTION]'], link='https://nyc.cs.berkeley.edu/uni/', link_label='Explore GamesmanUni'),
    dict(slug='orbito', title='Orbito: Designing a Two-Phase Turn', eyebrow='02 / GamesCrafters', outcome='Turning a rotating physical board game into a click interface that still feels real, on top of a solver covering 20M+ positions.', image='public/timeline/gc-orbito.png', alt='Orbito project image from the GamesCrafters timeline', caption='Orbito project image. Add a physical board comparison and digital interface capture.', role='Co-developer', team='Partner project, GamesCrafters', timeline='Fall 2025', tools='[ADD TOOLS]', skills='Game UI, interaction design, solver integration', tags=['Co-developer', 'Fall 2025', 'Game UI'], problem='A physical Orbito turn includes rotation and an optional second phase. The digital interface has to explain both the action and the possibility of skipping without making the player read a rulebook mid-turn.', process='The team first built a text interface to prove the solver, then moved to a graphical interface on GamesmanUni. The interaction question became how to expose an optional second phase so players know they can skip it. [ADD TURN FLOW DIAGRAM AND ITERATION SCREENSHOTS]', decisions=[('Prove behavior first', 'A text interface established the solver before graphical choices were layered on top.'), ('Keep the turn legible', 'The GUI needs to communicate which phase is active and what action is available. [ADD GUI SCREENSHOT]'), ('Make skipping visible', 'An explicit affordance for the optional second phase should be evaluated with players. [ADD TEST FINDING]')], result='The game was brought online on GamesmanUni on top of a solver covering more than 20 million positions. [ADD PLAYER TESTING OR FEEDBACK]', learned=['The rules of a physical game need a new explanation when translated to clicks.', 'An optional action still needs a clear interface.', '[ADD PERSONAL REFLECTION]'], link='https://nyc.cs.berkeley.edu/uni/', link_label='Visit GamesmanUni'),
    dict(slug='ballxpit', title='BALL x PIT Evolution Tracker', eyebrow='03 / Personal project', outcome='A player tool the community built on: Pit Crew uses my tracker as its foundation.', image='public/timeline/ballxpitTracker_thumbnail.png', alt='Screenshot of the BALL x PIT Evolution Tracker', caption='The tracker interface, built for quick reference while playing.', role='Designer and developer', team='Independent', timeline='[ADD TIMEFRAME]', tools='[ADD TOOLS]', skills='Player tools, information design, frontend development', tags=['Independent', 'Player tool', 'Community'], problem='Players need to keep track of evolutions and passives while making decisions in the middle of a run. The tracker grew from a problem I noticed while playing.', process='I built an evolution and passive tracker with a team-builder matchmaker to make the information quick to use mid-game. [ADD EARLY SKETCHES, ITERATION, AND PLAYER FEEDBACK]', decisions=[('Design for quick checks', 'Information should be scannable during play, when attention is split between the game and the tool.'), ('Connect build choices', 'The team-builder matchmaker brings related choices into the same workflow. [ADD DESIGN RATIONALE]'), ('Let the community extend it', 'Pit Crew uses the tracker as a foundation. [ADD CREDIT SCREENSHOT OR QUOTE]')], result='Pit Crew uses this tracker as its foundation. [ADD CREDIT AND USAGE FEEDBACK] No usage count is claimed here until it can be documented.', learned=['A personal friction point can reveal a broader player need.', 'A reference tool must be fast enough to use during play.', '[ADD PERSONAL REFLECTION]'], link='https://cryphixi.github.io/ballxpit-tracker/', link_label='Use the tracker'),
    dict(slug='levelforger', title='LevelForger', eyebrow='04 / AI4ALL', outcome='A generative model for game levels, with a validation pipeline that cut unplayable levels from 30% to 5%.', image='public/timeline/LevelForger_thumbnail.webp', alt='LevelForger project thumbnail showing generated game levels', caption='LevelForger project thumbnail. Add example levels and the validation pipeline.', role='AI4ALL fellow', team='AI4ALL', timeline='2025', tools='Generative model; [ADD FRAMEWORKS]', skills='Machine learning, game design, validation', tags=['AI4ALL', '2025', 'Human-centered AI'], problem='Generated content is only useful if a human can play it. The design challenge was to make level generation answer to a player-facing standard of playability.', process='I built a generative model for game levels and added a validation pipeline. The pipeline reduced unplayable outputs from 30% to 5%. [ADD GENERATED EXAMPLES AND PIPELINE DIAGRAM]', decisions=[('Validate the output', 'The validation pipeline checks playability before a generated level is treated as usable.'), ('Measure player relevance', 'The key metric is the share of levels a human can actually play, rather than generation alone.'), ('Show the limits', 'Examples should include both successful levels and failure cases. [ADD BEFORE/AFTER EXAMPLES]')], result='The validation pipeline cut unplayable levels from 30% to 5%. [ADD EVALUATION SET SIZE AND METHOD]', learned=['A model needs evaluation tied to the person using its output.', 'Validation changes a generation demo into a more useful tool.', '[ADD PERSONAL REFLECTION]'], link=None, link_label=None),
]


def tags(items):
    return '<ul class="tags">' + ''.join(f'<li>{escape(x)}</li>' for x in items) + '</ul>'


cards = ''
for s in studies:
    cards += f'''<article class="work-card reveal"><a class="cover-link" href="{s['slug']}.html" aria-label="Read {escape(s['title'])} case study"><img src="{s['image']}" alt="{escape(s['alt'])}" loading="lazy"></a><div class="card-body"><span class="eyebrow">{s['eyebrow']}</span><h3><a href="{s['slug']}.html">{escape(s['title'])} <span class="card-arrow" aria-hidden="true">↗</span></a></h3><p>{escape(s['outcome'])}</p>{tags(s['tags'])}</div></article>'''

home = f'''<section class="hero container"><p class="eyebrow">HCI / Game design / Engineering</p><h1>I design technology that adapts to people, using games as my lab.</h1><p class="hero-lead">HCI and game designer at UC Berkeley (CS + Data Science). I focus on player experience, onboarding, and learnability: interfaces that teach by doing, not walls of text.</p><p class="hero-status">Currently: Website Lead at GamesCrafters, applying to HCI master's programs for Fall 2027.</p><div class="button-row"><a class="button" href="#work">See my work ↓</a><a class="button secondary" href="resume.html">Resume ↗</a></div></section>
<section class="section container" id="work"><span id="projects" aria-hidden="true"></span><div class="section-head"><div><p class="eyebrow">Selected work / 01–04</p><h2>Design in practice</h2></div><p>Four projects about helping people find their way through games and tools.</p></div><div class="work-grid">{cards}</div></section>
<section class="section container"><p class="eyebrow">What I focus on</p><h2>People first, even in play</h2><div class="pillars"><article class="pillar reveal"><span class="symbol" aria-hidden="true">↗</span><h3>Onboarding & learnability</h3><p>Making the first step clear and letting an interface teach through action.</p></article><article class="pillar reveal"><span class="symbol" aria-hidden="true">◎</span><h3>Player experience</h3><p>Translating game rules and complex choices into understandable interactions.</p></article><article class="pillar reveal"><span class="symbol" aria-hidden="true">✳</span><h3>Human-centered AI</h3><p>Evaluating generated content by whether people can actually use it.</p></article></div></section>
<aside class="proof"><div class="container"><p class="eyebrow">A few signals</p><ul class="proof-list"><li><strong>Community</strong>Pit Crew built on my tracker</li><li><strong>20M+</strong>Orbito positions in the solver</li><li><strong>Teaching</strong>Game development with iD Tech and Girls Make Games</li></ul></div></aside>'''
(ROOT / 'index.html').write_text(shell('HCI & game design portfolio', 'Work', home, 'Allena Oglivie designs player experiences, onboarding, and human-centered technology.'), encoding='utf-8')


for i, s in enumerate(studies):
    decisions = ''.join(f'<article class="decision"><h3>{escape(head)}</h3><p>{escape(copy)}</p></article>' for head, copy in s['decisions'])
    lessons = ''.join(f'<li>{escape(x)}</li>' for x in s['learned'])
    meta = ''.join(f'<dt>{k}</dt><dd>{escape(s[v])}</dd>' for k, v in [('Role','role'),('Team','team'),('Timeline','timeline'),('Tools','tools'),('Skills','skills')])
    next_s = studies[(i + 1) % len(studies)]
    visit = f'<p><a class="button" href="{s["link"]}">{s["link_label"]} ↗</a></p>' if s['link'] else ''
    body = f'''<div class="container"><header class="page-intro"><p class="eyebrow">{s['eyebrow']} / Case study</p><h1>{escape(s['title'])}</h1><p>{escape(s['outcome'])}</p><a href="index.html#work">← All work</a></header><figure><img class="study-cover" src="{s['image']}" alt="{escape(s['alt'])}"><figcaption>{escape(s['caption'])}</figcaption></figure><div class="study-layout"><div class="study-copy"><section><p class="eyebrow">01 / The problem</p><h2>Who needed a better experience?</h2><p>{escape(s['problem'])}</p></section><section><p class="eyebrow">02 / Process</p><h2>From observation to iteration</h2><p>{escape(s['process'])}</p><div class="placeholder">[ADD IMAGE] Research notes, sketches, wireframes, or an iteration with a caption explaining what changed.</div></section><section><p class="eyebrow">03 / Decisions</p><h2>What shaped the design</h2><div class="decision-grid">{decisions}</div></section><section><p class="eyebrow">04 / Outcome</p><h2>What happened</h2><p>{escape(s['result'])}</p>{visit}</section><section><p class="eyebrow">05 / Reflection</p><h2>What I learned</h2><ul>{lessons}</ul></section></div><aside class="meta" aria-label="Project overview"><p class="eyebrow">Project overview</p><dl>{meta}</dl></aside></div><a class="next-project" href="{next_s['slug']}.html">Next project: {escape(next_s['title'])} →</a></div>'''
    (ROOT / f"{s['slug']}.html").write_text(shell(s['title'], 'Work', body, s['outcome']), encoding='utf-8')


about = '''<div class="container"><header class="page-intro"><p class="eyebrow">About / Allena Oglivie</p><h1>Design starts with the person using it.</h1><p>We should not conform to the tools meant to make our lives easier. The tools should conform to us.</p></header><div class="about-grid"><div><section class="section"><h2>Why I work this way</h2><p>I learned computers on my grandfather's 1980s machines. The question I still come back to is: “What if my grandmother used this?” Games made that question feel concrete. Portal showed me how a system can teach through the experience itself.</p><p>At UC Berkeley, I study computer science and data science and use those skills to build and test interfaces. I care about accessibility, privacy-first AI, and equity for marginalized communities.</p></section><section class="section"><p class="eyebrow">A condensed journey</p><h2>Where the work comes from</h2><ol class="timeline-list"><li><time>2025–present</time>Website Lead at GamesCrafters: GamesmanUni redesign and player-facing game interfaces.</li><li><time>2025</time>AI4ALL fellowship: LevelForger and player-centered evaluation of generated levels.</li><li><time>2023–2026</time>Computer science and data science at UC Berkeley; game development, graphics, and UI coursework.</li><li><time>Before Berkeley</time>Girls Make Games scholarship, America On Tech, and the first esports team at Alexander Hamilton Senior High.</li></ol><p><a href="archive.html">Explore the full visual timeline →</a></p></section><section class="section"><h2>Communities and teaching</h2><p>GamesCrafters · AI4ALL · Girls Make Games · iD Tech · EOP SSS STEM Scholar · Grace Hopper Celebration ’25</p><p><a href="organizations.html">See the organizations archive →</a></p></section></div><figure><img class="portrait" src="public/profile-portrait.jpg" alt="Portrait of Allena Oglivie"><figcaption>Allena Oglivie</figcaption></figure></div></div>'''
(ROOT / 'about.html').write_text(shell('About', 'About', about, 'About Allena Oglivie, an HCI and game designer at UC Berkeley.'), encoding='utf-8')

