    ('Snowfall / CS184', 'Graphics coursework and a snow rendering final project.', 'https://c-herbert.github.io/cs184-final-project-webpage/'),
    ('CS184 coursework', 'Rasterizer, MeshEdit, PathTracer, and Cloth Simulation.', 'https://cal-cs184-student.github.io/hw-webpages-Cryphixi/'),
