lab_cards = ''.join(f'<article class="lab-item reveal"><h3>{escape(n)}</h3><p>{escape(d)}</p><a href="{u}">Explore ↗</a></article>' for n,d,u in lab_items)
lab = f'''<div class="container"><header class="page-intro"><p class="eyebrow">Play / Lab</p><h1>Experiments, games, and things in progress.</h1><p>A wider collection of coursework, community tools, game concepts, and the original site archive.</p></header><div class="lab-grid">{lab_cards}</div></div>'''
(ROOT / 'lab.html').write_text(shell('Play & Lab', 'Lab', lab, 'Experiments, coursework, games, and tools by Allena Oglivie.'), encoding='utf-8')

resume = '''<div class="container"><header class="page-intro"><p class="eyebrow">Resume</p><h1>Design, code, and community.</h1><p>HCI and game design at UC Berkeley, with work across research platforms, game interfaces, and player-facing tools.</p><div class="button-row"><a class="button" href="public/Allena_Oglivie_Resume.pdf">Open resume PDF ↗</a><a class="button secondary" href="mailto:ogfay05@gmail.com">Get in touch</a></div></header><section class="section"><h2>At a glance</h2><div class="pillars"><div class="pillar"><h3>Design</h3><p>Website Lead at GamesCrafters, focused on navigation, learnability, and game UI.</p></div><div class="pillar"><h3>Engineering</h3><p>Computer science and data science at UC Berkeley; frontend work and game solvers.</p></div><div class="pillar"><h3>Community</h3><p>Girls Make Games, iD Tech, AI4ALL, and EOP SSS STEM Scholar.</p></div></div></section><section class="section"><h2>Full resume</h2><iframe class="resume-frame" src="public/Allena_Oglivie_Resume.pdf#view=FitH" title="Allena Oglivie resume PDF"></iframe><p><a href="public/Allena_Oglivie_Resume.pdf">Download the PDF if the preview is unavailable →</a></p></section></div>'''
(ROOT / 'resume.html').write_text(shell('Resume', 'Resume', resume, 'Resume and experience summary for Allena Oglivie.'), encoding='utf-8')
